 1→apiVersion: v1
 2→kind: ConfigMap
 3→metadata:
 4→  name: {{ .Values.configMapName | default "cmn-search-config" }}
 5→  namespace: {{ .Release.Namespace }}
 6→data:
 7→  ####################### Infra #######################
 8→  # Elasticsearch 공통 설정
 9→  {{- with .Values.elasticsearch }}
10→  ELASTICSEARCH_URLS: {{ .urls | quote }}
11→  ELASTICSEARCH_CONNECTION_TIMEOUT: {{ .connectionTimeout | quote }}
12→  ELASTICSEARCH_SOCKET_TIMEOUT: {{ .socketTimeout | quote }}
13→  {{- end }}
14→
15→  # Valkey Front 클러스터
16→  {{- with .Values.valkey.front }}
17→  VALKEY_FRONT_HOST: {{ .host | quote }}
18→  VALKEY_FRONT_PORT: {{ .port | quote }}
19→  VALKEY_FRONT_DATABASE: {{ .database | quote }}
20→  VALKEY_FRONT_MAX_CONNECTION: {{ .maxConnection | quote }}
21→  VALKEY_FRONT_CLUSTER_MODE: {{ .clusterMode | quote }}
22→  {{- end }}
23→
24→  # Valkey Back 클러스터
25→  {{- with .Values.valkey.backend }}
26→  VALKEY_BACKEND_HOST: {{ .host | quote }}
27→  VALKEY_BACKEND_PORT: {{ .port | quote }}
28→  VALKEY_BACKEND_DATABASE: {{ .database | quote }}
29→  VALKEY_BACKEND_MAX_CONNECTION: {{ .maxConnection | quote }}
30→  VALKEY_BACKEND_CLUSTER_MODE: {{ .clusterMode | quote }}
31→  {{- end }}
32→
33→  # MongoDB 공통 설정
34→  {{- with .Values.mongodb }}
35→  MONGODB_BACKEND_URL: {{ .url | quote }}
36→  MONGODB_BACKEND_DB: {{ .db | quote }}
37→  {{- end }}
38→
39→  # Keyword Analysis 공통 설정
40→  {{- with .Values.keywordAnalysis }}
41→  KEYWORD_ANALYSIS_URL: {{ .url | quote }}
42→  KEYWORD_ANALYSIS_CONNECTION_TIMEOUT: {{ .connectionTimeout | quote }}
43→  KEYWORD_ANALYSIS_SOCKET_TIMEOUT: {{ .socketTimeout | quote }}
44→  {{- end }}
45→

 1→apiVersion: v1
 2→kind: ConfigMap
 3→metadata:
 4→  name: {{ include "legacy-sync.fullname" . }}-config
 5→  labels:
 6→    {{- include "legacy-sync.labels" . | nindent 4 }}
 7→data:
 8→  # ===== 서비스 특화 설정 (공통 ConfigMap에 없는 것들) =====
 9→  OTEL_SERVICE_NAME: {{ .Values.otelServiceName | quote }}
10→  OTEL_EXPORTER_OTLP_ENDPOINT: {{ .Values.otel.endpoint | quote }}
11→  OTEL_TRACES_EXPORTER: {{ .Values.otel.tracesExporter | quote }}
12→  OTEL_METRICS_EXPORTER: {{ .Values.otel.metricsExporter | quote }}
13→  OTEL_LOGS_EXPORTER: {{ .Values.otel.logsExporter | quote }}
14→  OTEL_INSTRUMENTATION_MICROMETER_ENABLED: {{ .Values.otel.micrometerEnabled | quote }}
15→  JAVA_TOOL_OPTIONS: >
16→    -javaagent:{{ .Values.otel.agentPath }}
17→    -Dotel.experimental.config.file={{ .Values.otel.otelConfig }}
18→
19→  # Search index configuration
20→  SEARCH_INDEX_ADMIN_CATALOG: {{ .Values.config.index.adminCatalog | quote }}
21→  SEARCH_INDEX_ADMIN_PRODUCT: {{ .Values.config.index.adminProduct | quote }}
22→

